/** Sorted list of distinct tags across a club list (defaults to the fallback list). */
export function getAllTags(list = clubs) {
  const set = new Set();
  list.forEach((c) => {
    (c.Club_Tags || "")
      .split(",")
      .map((t) => t.trim())
      .filter(Boolean)
      .forEach((t) => set.add(t));
  });
  return Array.from(set).sort();
}
